      works: wl.map(([id, title, who, day, kind]) => { const d = !!fb[id]; return { title, who, day, kind, st: d ? '已回饋' : '待審閱', cls: d ? 'on' : '', ring: s.w === id ? '#1f1f1f' : '#d6d6d2', ringW: s.w === id ? '2px' : '1px', pick: () => this.setState({ w: id, good: '', tip: '' }) }; }),
